$types=$types??[]; $activeVerification=$activeVerification??null; $latestRequest=$latestRequest??null; $cooldown=$cooldown??['active'=>false,'remaining_seconds'=>0,'until'=>null]; $cooldownHours=(int)($cooldownHours??72); $error=$error??''; $success=$success??'';
$flashError=(string)($_SESSION['flash_error']??''); unset($_SESSION['flash_error']);
$flashSuccess=(string)($_SESSION['flash_success']??''); unset($_SESSION['flash_success']);
if ($error === '' && $flashError !== '') $error = $flashError;
if ($success === '' && $flashSuccess !== '') $success = $flashSuccess;
$siteCfg=(new \App\Models\SettingModel())->getSiteConfig();
function web_verify_color(string $color): string { return preg_match('/^#[0-9a-fA-F]{6}$/', $color) ? $color : '#2563eb'; }
function web_verify_v(string $color): string { $color = web_verify_color($color); return '<span class="verify-v" style="--v-color:'.htmlspecialchars($color, ENT_QUOTES).'">V</span>'; }
function web_verify_name(string $name, string $color): string { return '<strong class="verify-name" style="color:'.htmlspecialchars(web_verify_color($color), ENT_QUOTES).'">'.htmlspecialchars($name, ENT_QUOTES).'</strong>'; }
function old_verify_value(string $key): string { return htmlspecialchars((string)($_POST[$key] ?? ''), ENT_QUOTES); }
function verify_remaining_text(int $seconds): string { $seconds=max(0,$seconds); $d=intdiv($seconds,86400); $seconds%=86400; $h=intdiv($seconds,3600); $seconds%=3600; $m=intdiv($seconds,60); if($d>0)return $d.'天'.$h.'小时'; if($h>0)return $h.'小时'.$m.'分钟'; return max(1,$m).'分钟'; }
