n-box{border:1px solid #fed7aa;background:#fff7ed;color:#9a3412;border-radius:16px;padding:14px}.cooldown-time{font-size:22px;font-weight:950;color:#ea580c;margin:8px 0 4px}.muted{color:var(--text-muted,#94a3b8);font-size:13px;line-height:1.7}.verify-head-actions .btn,.danger-link{height:34px!important;min-height:34px!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;line-height:1!important;text-align:center!important;white-space:nowrap!important;vertical-align:middle!important;padding:0 12px!important;border-radius:999px!important;font-size:12px!important;font-weight:900!important}.danger-link{border:1px solid rgba(239,68,68,.24);background:rgba(239,68,68,.06);color:#ef4444;cursor:pointer}.danger-link:hover{background:rgba(239,68,68,.1)}html[data-theme="dark"] .verify-card{background:#111827;border-color:#263244;box-shadow:0 10px 30px rgba(0,0,0,.25)}html[data-theme="dark"] .type-option{background:#0f172a;border-color:#263244}html[data-theme="dark"] .cooldown-box{background:#431407;border-color:#9a3412;color:#fed7aa}@media(max-width:640px){.verify-page{padding:14px 12px 104px}.verify-card{border-radius:18px;padding:16px}.verify-title{font-size:22px}.verify-head{align-items:flex-start}.verify-head-actions{gap:6px}.verify-head-actions .btn,.danger-link{height:32px!important;padding:0 10px!important;font-size:12px!important}}
</style></head><body><?php require dirname(__DIR__) . '/layouts/topbar.php'; ?><main class="verify-page"><div class="verify-shell"><div class="verify-head"><div class="verify-title">申请认证</div><div class="verify-head-actions"><?php if($activeVerification): ?><form method="post" action="/index.php?path=verification/revoke" onsubmit="return confirm('撤销后将进入重新认证冷却期，确认撤销当前认证？')"><?= csrf_field() ?><button class="danger-link" type="submit">撤销认证</button></form><?php endif; ?><a class="btn btn-light" style="text-decoration:none;" href="/index.php?path=me">返回个人中心</a></div></div><?php if($error): ?><div class="alert err"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert ok"><?= htmlspecialchars($success) ?></div><?php endif; ?>
<?php if($activeVerification): ?><section class="verify-card"><h2>当前认证</h2><p><?= web_verify_v((string)$activeVerification['verification_color']) ?> <?= web_verify_name((string)$activeVerification['verification_name'], (string)$activeVerification['verification_color']) ?></p><p class="muted">认证时间：<?= htmlspecialchars((string)$activeVerification['verified_at']) ?></p><p class="muted">已认证账号不能重复提交申请。如需更换认证，请先点击右上角“撤销认证”。</p></section><?php endif; ?>
<?php if(!$activeVerification && !empty($cooldown['active'])): ?><section class="verify-card"><h2>重新认证冷却中</h2><div class="cooldown-box"><div>你刚撤销过认证，冷却结束后才可以重新申请。</div><div class="cooldown-time" data-cooldown-seconds="<?= (int)($cooldown['remaining_seconds'] ?? 0) ?>"><?= htmlspecialchars(verify_remaining_text((int)($cooldown['remaining_seconds'] ?? 0))) ?></div><div class="muted">预计可申请时间：<?= htmlspecialchars((string)($cooldown['until'] ?? '')) ?></div></div></section><?php endif; ?>
<?php if($latestRequest): ?><section class="verify-card"><h2>最近申请</h2><p><span class="status-pill"><?= ['pending'=>'审核中','approved'=>'已通过','rejected'=>'已驳回','cancelled'=>'已取消'][$latestRequest['status']] ?? $latestRequest['status'] ?></span> <?= web_verify_v((string)$latestRequest['verification_color']) ?> <?= web_verify_name((string)$latestRequest['verification_name'], (string)$latestRequest['verification_color']) ?></p><?php if(!empty($latestRequest['review_note'])): ?><p class="muted">审核备注：<?= htmlspecialchars((string)$latestRequest['review_note']) ?></p><?php endif; ?></section><?php endif; ?>
<section class="verify-card"><h2>提交认证申请</h2><?php if($activeVerification): ?><p class="muted">你已通过认证，暂不能重复申请。</p><?php elseif(!empty($cooldown['active'])): ?><p class="muted">当前处于撤销认证后的冷却期，倒计时结束后这里会恢复申请入口。</p><?php elseif($latestRequest && ($latestRequest['status'] ?? '')==='pending'): ?><p class="muted">你已有申请正在审核中，请等待审核结果。</p><?php elseif(empty($types)): ?><p class="muted">当前暂无开放申请的认证类型。</p><?php else: ?><form class="verify-form" method="post" action="/index.php?path=verification/apply"><?= csrf_field() ?><label>认证名称（展示用，最多8个字）<input class="input" name="display_name" maxlength="8" value="<?= old_verify_value('display_name') ?>" placeholder="如 官方认证" required></label><div class="type-list"><?php foreach($types as $t): ?><label class="type-option"><input type="radio" name="type_id" value="<?= (int)$t['id'] ?>" required><div><div class="type-name"><?= web_verify_v((string)$t['color']) ?> <?= web_verify_name((string)$t['name'], (string)$t['color']) ?></div><?php if(!empty($t['description']) || !empty($t['apply_note'])): ?><div class="type-desc"><?= htmlspecialchars((string)($t['description'] ?: $t['apply_note'])) ?></div><?php endif; ?></div></label><?php endforeach; ?></div><label>真实姓名/主体名称（可选）<input class="input" name="real_name" value="<?= old_verify_value('real_name') ?>" placeholder="个人姓名、机构名或品牌名"></label><label>申请说明/证明材料<textarea class="textarea" name="material" placeholder="请说明你申请该认证的原因、身份依据或可核验链接。" required><?= old_verify_value('material') ?></textarea></label><button class="btn btn-primary" type="submit">提交申请</button></form><?php endif; ?></section></div></main><?php require dirname(__DIR__, 2) . '/layouts/theme-toggle.php'; ?><?php require dirname(__DIR__) . '/layouts/bottom-nav.php'; ?><script>(function(){var el=document.querySelector('[data-cooldown-seconds]');if(!el)return;var s=parseInt(el.dataset.cooldownSeconds||'0',10);function fmt(n){n=Math.max(0,n);var d=Math.floor(n/86400);n%=86400;var h=Math.floor(n/3600);n%=3600;var m=Math.floor(n/60);if(d>0)return d+'天'+h+'小时';if(h>0)return h+'小时'+m+'分钟';return Math.max(1,m)+'分钟';}setInterval(function(){s--;el.textContent=fmt(s);if(s<=0)location.reload();},1000);})();</script></body></html>
